package com.aveycole.agentlooper;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.media.*;
import android.media.projection.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;

public final class MainActivity extends Activity {
    final LoopEngine engine=AudioService.engine;
    LooperView surface;
    MidiControl midi;
    int selected,transferBank;
    LoopEngine pendingExport;
    int desiredMode;
    static final int MIC=10,PROJECTION=11,EXPORT=12,IMPORT=13,SAVE=14,LOAD=15;
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);getWindow().setStatusBarColor(0xff0c0f13);surface=new LooperView(this);setContentView(surface);surface.setOnApplyWindowInsetsListener((v,insets)->{surface.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});midi=new MidiControl(this);if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED)startAudio(null);else requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},MIC);}
    void startAudio(Intent grant){Intent i=new Intent(this,AudioService.class);if(grant!=null)i.putExtra("grant",grant);try{startForegroundService(i);}catch(Exception e){engine.message=e.getMessage();}}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==MIC){if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED)startAudio(null);else{engine.message="Microphone permission required for recording";startAudio(null);}}}
    void transport(int bank,int action){selected=bank;if(AudioService.current==null){startAudio(null);engine.message="Starting audio — tap again";return;}try{synchronized(engine){if(action==0)engine.begin(bank,false);if(action==1)engine.begin(bank,true);if(action==2)engine.stop(bank);if(action==3)engine.undo(bank);if(action==4)engine.banks[bank].auto=!engine.banks[bank].auto;}saveLocal();}catch(OutOfMemoryError e){engine.message="Memory full — export and remove layers";}catch(Exception e){engine.message=e.getMessage();}}
    void saveLocal(){AudioService s=AudioService.current;if(s!=null)s.save();}
    AlertDialog.Builder dialog(String title){return new AlertDialog.Builder(this,android.R.style.Theme_Material_Dialog_Alert).setTitle(title);}
    void choice(String title,String[] items,int checked,java.util.function.IntConsumer action){AlertDialog d=dialog(title).setSingleChoiceItems(items,checked,(which,index)->{which.dismiss();action.accept(index);surface.invalidate();}).setNegativeButton("CLOSE",null).create();d.show();}
    void timing(){String[] names={"BPM", "BEATS / MEASURE", "MEASURES", "COUNT-IN"};choice("Timing",names,-1,index->{if(index==0)number("BPM",engine.bpm,20,300,v->engine.bpm=v);if(index==1)choice("Beats / measure",new String[]{"2 / 4","3 / 4","4 / 4","5 / 4","6 / 4","7 / 4"},engine.beats-2,n->engine.beats=n+2);if(index==2)choice("Measures",new String[]{"1","2","3","4","8","16"},-1,n->engine.bars=new int[]{1,2,3,4,8,16}[n]);if(index==3)choice("Count-in",new String[]{"OFF","1 MEASURE","2 MEASURES"},engine.countIn,n->engine.countIn=n);saveLocal();});}
    void number(String title,double value,double min,double max,java.util.function.DoubleConsumer action){EditText input=new EditText(this);input.setTextColor(Color.WHITE);input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL|android.text.InputType.TYPE_NUMBER_FLAG_SIGNED);input.setText(String.format(Locale.US,"%.2f",value));input.selectAll();dialog(title).setView(input).setPositiveButton("SET",(d,w)->{try{double v=Double.parseDouble(input.getText().toString());if(!Double.isFinite(v)||v<min||v>max)throw new Exception();action.accept(v);saveLocal();}catch(Exception e){engine.message="Use a value from "+min+" to "+max;}}).setNegativeButton("CANCEL",null).show();}
    void routing(int bank){selected=bank;LoopEngine.Bank b=engine.banks[bank];String peer=bank==0?"B":"A";choice("Looper "+(bank==0?"A":"B"),new String[]{b.sync?"SYNC · ON":"SYNC · OFF","START · "+new String[]{"NOW","MEASURE",peer+" LOOP"}[b.quantize],"INPUT · "+new String[]{"LIVE","A","LIVE + A"}[b.inputMode],b.waitInput?"WAIT FOR INPUT · ON":"WAIT FOR INPUT · OFF","TRIGGER · "+(int)b.triggerDb+" dBFS"},-1,n->{if(n==0)b.sync=!b.sync;if(n==1)choice("Start",new String[]{"NOW","MEASURE",peer+" LOOP"},b.quantize,q->{engine.finish(bank,false);b.quantize=q;});if(n==2&&bank==1)choice("Input",new String[]{"LIVE","A","LIVE + A"},b.inputMode,q->{engine.finish(bank,false);b.inputMode=q;});if(n==3)b.waitInput=!b.waitInput;if(n==4)number("Input trigger dBFS",b.triggerDb,-72,-6,v->b.triggerDb=v);saveLocal();});}
    void audioMenu(){AudioService s=AudioService.current;choice("Audio",new String[]{"INPUT","CHANNELS","OUTPUT",s!=null&&s.ready?s.route:"START AUDIO","END APP CAPTURE",AudioService.monitor?"INPUT MONITOR · ON":"INPUT MONITOR · OFF","MONITOR LEVEL"},-1,n->{if(n==0)inputMenu();if(n==1)channelsMenu();if(n==2)outputMenu();if(n==3)startAudio(null);if(n==4){AudioService service=AudioService.current;if(service!=null)service.endCapture();}if(n==5)monitorToggle();if(n==6)number("Monitor level %",AudioService.monitorGain*100,0,100,v->AudioService.monitorGain=v/100);});}
    void monitorToggle(){if(AudioService.monitor){AudioService.monitor=false;return;}dialog("Input monitoring").setMessage("Use headphones. Mic monitoring through speakers can cause loud feedback. Hardware direct monitoring can also double the level.").setNegativeButton("CANCEL",null).setPositiveButton("ENABLE",(d,w)->AudioService.monitor=true).show();}
    void reconfigure(){synchronized(engine){engine.finish(0,false);engine.finish(1,false);}AudioService s=AudioService.current;if(s!=null)s.queueReopen();else startAudio(null);}
    void inputMenu(){AudioManager manager=(AudioManager)getSystemService(AUDIO_SERVICE);ArrayList<AudioDeviceInfo> devices=new ArrayList<>();ArrayList<String> names=new ArrayList<>();names.add("Microphone");names.add("Other apps");names.add("Mic + apps");for(AudioDeviceInfo d:manager.getDevices(AudioManager.GET_DEVICES_INPUTS)){if(d.getType()!=AudioDeviceInfo.TYPE_BUILTIN_MIC){devices.add(d);names.add(d.getProductName().toString());}}choice("Input",names.toArray(new String[0]),-1,n->{if(n==1||n==2){if(Build.VERSION.SDK_INT<29){engine.message="Other-app capture needs Android 10+";return;}desiredMode=n;MediaProjectionManager pm=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);Intent capture=Build.VERSION.SDK_INT>=34?pm.createScreenCaptureIntent(MediaProjectionConfig.createConfigForDefaultDisplay()):pm.createScreenCaptureIntent();startActivityForResult(capture,PROJECTION);return;}AudioService.mode=0;AudioService.left=AudioService.right=0;if(n==0){AudioService.inputId=0;for(AudioDeviceInfo d:manager.getDevices(AudioManager.GET_DEVICES_INPUTS))if(d.getType()==AudioDeviceInfo.TYPE_BUILTIN_MIC){AudioService.inputId=d.getId();break;}}else AudioService.inputId=devices.get(n-3).getId();reconfigure();});}
    void channelsMenu(){AudioManager m=(AudioManager)getSystemService(AUDIO_SERVICE);AudioDeviceInfo source=null;for(AudioDeviceInfo d:m.getDevices(AudioManager.GET_DEVICES_INPUTS))if(d.getId()==AudioService.inputId)source=d;int count=1;if(source!=null)for(int c:source.getChannelCounts())count=Math.max(count,c);count=Math.min(count,24);ArrayList<String> names=new ArrayList<>();ArrayList<int[]> values=new ArrayList<>();for(int c=0;c<count;c++){names.add("MONO · "+(c+1));values.add(new int[]{c,c});}for(int c=0;c+1<count;c+=2){names.add("STEREO · "+(c+1)+" / "+(c+2));values.add(new int[]{c,c+1});}choice("Input channels",names.toArray(new String[0]),-1,n->{int[] pair=values.get(n);AudioService.left=pair[0];AudioService.right=pair[1];reconfigure();});}
    void outputMenu(){AudioManager m=(AudioManager)getSystemService(AUDIO_SERVICE);AudioDeviceInfo[] devices=m.getDevices(AudioManager.GET_DEVICES_OUTPUTS);String[] names=new String[devices.length+1];names[0]="System default";for(int i=0;i<devices.length;i++)names[i+1]=devices[i].getProductName().toString();choice("Output",names,-1,n->{AudioService.outputId=n==0?0:devices[n-1].getId();reconfigure();});}
    void fileMenu(){choice("Files · "+(selected==0?"A":"B"),new String[]{"IMPORT WAV","EXPORT WAV","SAVE SESSION","OPEN SESSION","SAVE ON DEVICE"},-1,n->{transferBank=selected;Intent i;if(n==0){i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("audio/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT);}if(n==1){synchronized(engine){if(engine.banks[selected].recording){engine.message="Finish recording before export";return;}if(engine.banks[selected].layers.isEmpty()){engine.message="Record a loop first";return;}}pendingExport=AudioFiles.snapshot(engine,selected);i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("audio/wav").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"Agent Looper "+(selected==0?"A":"B")+".wav");startActivityForResult(i,EXPORT);}if(n==2){i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/octet-stream").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"Agent Looper.agl");startActivityForResult(i,SAVE);}if(n==3){i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,LOAD);}if(n==4){saveLocal();engine.message="Session save queued";}});}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PROJECTION){if(result==RESULT_OK&&data!=null){synchronized(engine){engine.finish(0,false);engine.finish(1,false);}AudioService.mode=desiredMode;startAudio(data);}else engine.message="App capture was not enabled";return;}if(result!=RESULT_OK||data==null)return;Uri uri=data.getData();new Thread(()->{try{if(request==IMPORT){float[] audio;try(InputStream in=getContentResolver().openInputStream(uri)){audio=AudioFiles.readWav(in);}synchronized(engine){LoopEngine.Bank b=engine.banks[transferBank];if(b.layers.size()>=LoopEngine.MAX_LAYERS)throw new IOException("Layer limit reached");LoopEngine.Layer l=new LoopEngine.Layer(audio,"Imported",b.frame);b.layers.add(l);if(b.layers.size()==1){b.origin=b.frame;b.period=l.frames();}}}if(request==EXPORT){try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){AudioFiles.export(pendingExport,out);}pendingExport=null;}if(request==SAVE){synchronized(engine){engine.finish(0,false);engine.finish(1,false);}try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){engine.snapshot().save(out);}}if(request==LOAD){synchronized(engine){engine.finish(0,false);engine.finish(1,false);}try(InputStream in=getContentResolver().openInputStream(uri)){engine.load(in);}}engine.message="DONE";saveLocal();}catch(Exception|OutOfMemoryError e){engine.message=e.getMessage()==null?"Not enough memory":e.getMessage();}},"Agent Looper files").start();}
    void learn(int bank,int action){midi.learn(bank*5+action);}
    @Override protected void onStop(){saveLocal();super.onStop();}
    @Override protected void onDestroy(){if(midi!=null)midi.close();super.onDestroy();}
}
